using System;

public static class Dates
{
    public static DateTime AddBusinessDays(DateTime start, int n)
    {
        if (n == 0)
        {
            return start;
        }
        var current = start;
        var counted = 0;
        while (counted < n)
        {
            current = current.AddDays(1);
            if (current.DayOfWeek != DayOfWeek.Saturday && current.DayOfWeek != DayOfWeek.Sunday)
            {
                counted++;
            }
        }
        return current;
    }
}

