using System;

public static class Dates
{
    public static DateTime AddBusinessDays(DateTime start, int n)
    {
        if (n == 0)
        {
            return start;
        }
        var weeks = n / 5;
        var remainder = n % 5;
        var calendarDays = weeks * 7 + remainder;
        return start.AddDays(calendarDays);
    }
}

