using System;
using Xunit;

public class DatesTests
{
    [Fact]
    public void ZeroReturnsStartUnchanged()
    {
        var d = new DateTime(2024, 6, 1); // Saturday
        Assert.Equal(d, Dates.AddBusinessDays(d, 0));
    }

    [Fact]
    public void FridayPlusOneSkipsWeekend()
    {
        var friday = new DateTime(2024, 5, 31);
        Assert.Equal(new DateTime(2024, 6, 3), Dates.AddBusinessDays(friday, 1));
    }

    [Fact]
    public void MondayPlusFiveLandsNextMonday()
    {
        var monday = new DateTime(2024, 5, 27);
        Assert.Equal(new DateTime(2024, 6, 3), Dates.AddBusinessDays(monday, 5));
    }

    [Fact]
    public void CrossesMonthAndYearBoundary()
    {
        var friday = new DateTime(2024, 12, 27);
        Assert.Equal(new DateTime(2025, 1, 1), Dates.AddBusinessDays(friday, 3));
    }

    [Fact]
    public void StartingOnAWeekendStillCountsCorrectly()
    {
        var saturday = new DateTime(2024, 6, 1);
        Assert.Equal(new DateTime(2024, 6, 3), Dates.AddBusinessDays(saturday, 1));
    }
}
